\textbf{Multitask Multiscale Network (s=5, 60s)} \quad & \underline{54.4} & \underline{26.1} & \textbf{84.1} & \textbf{55.2} & \textbf{55.0} \\
\quad w/o. MMoE & 52.8 & 22.0 & 82.9 & 51.8 & 52.4 \\
\quad w/o. Data Augmentation & 50.5 & 19.6 & 83.2 & 51.7 & 51.2 \\
\quad w/o. Temporal Scaling (s=1) & 50.5 & 13.3 & 80.3 & 41.9 & 46.5 \\
\quad uses Temporal Scaling s=3 & 51.1 & \underline{26.1} & \textbf{84.1} & \underline{54.3} & 53.9 \\
